const TAB_ICONS: Record<string, React.FC> = {
  support: SupportIcon,
  membership: MembershipIcon,
  courses: CoursesIcon,
  certification: CertificationIcon,
  glossary: GlossaryIcon,
};

type ViewState = 'home' | 'detail' | 'search';

// ─── Screen ─────────────────────────────────────────────────────────────────

const HelpSupportScreen = ({navigation}: any) => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [view, setView] = useState<ViewState>('home');
  const [loading, setLoading] = useState(true);
  const [errored, setErrored] = useState(false);

  const [heroTitle, setHeroTitle] = useState('How can we help you?');
  const [tabs, setTabs] = useState<HubTab[]>([]);
  const [activeTab, setActiveTab] = useState<HubTab | null>(null);

  const [faqs, setFaqs] = useState<Faq[]>([]);
  const [glossary, setGlossary] = useState<GlossaryTerm[]>([]);
  const [glossaryQuery, setGlossaryQuery] = useState('');
  const [glossaryResult, setGlossaryResult] = useState<GlossaryTerm | null>(null);

  const [query, setQuery] = useState('');
  const [searchLoading, setSearchLoading] = useState(false);
  const [searchResults, setSearchResults] = useState<Faq[]>([]);

  const [activeFaq, setActiveFaq] = useState<Faq | null>(null);
  const [activeFaqBlocks, setActiveFaqBlocks] = useState<FaqContentBlock[]>([]);
  const [relatedFaqs, setRelatedFaqs] = useState<Faq[]>([]);
  const [detailLoading, setDetailLoading] = useState(false);

  useEffect(() => {
    loadInitial();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadInitial = async () => {
    setLoading(true);
    setErrored(false);
    const page = await getHubPage();
    const allTabs = await getHubTabs();
    if (page) setHeroTitle(page.banner_title || page.title || 'How can we help you?');
    setTabs(allTabs);
    const support = allTabs.find(t => t.id === 'support') || allTabs[0] || null;
    if (support) {
      await selectTab(support);
    } else {
      setErrored(true);
    }
    setLoading(false);
  };

  const selectTab = async (tab: HubTab) => {
    setActiveTab(tab);
    setView('home');
    if (tab.type === 'glossary') {
      const terms = await getGlossary();
      setGlossary(terms);
      setFaqs([]);
    } else {
      const data = await getSupportHubTab(tab.endpoint);
      setFaqs(data?.faqs ?? []);
    }
  };

  const handleSearch = async () => {
    const q = query.trim();
    if (!q) return;
    setSearchLoading(true);
    setView('search');
    const result = await searchSupportHub(q);
    setSearchResults(result.faqs);
    setSearchLoading(false);
  };

  const handleGlossarySearch = () => {
    const match = searchGlossary(glossaryQuery, glossary);
    setGlossaryResult(match[0] || null);
    setView('search');
  };

  const openFaq = async (faq: Faq) => {
    setDetailLoading(true);
    setView('detail');
    const full = await getFaqDetail(faq);
    setActiveFaq(full);
    setActiveFaqBlocks(parseFaqHtml(full.content_html || ''));
    // Related = other FAQs from the same list currently loaded (search
    // results or the active tab's list) sharing a category.
    const pool = view === 'search' ? searchResults : faqs;
    const related = getRelatedFaqs(
      full,
      pool.filter(f => f.categories?.some(c => full.categories?.some(fc => fc.slug === c.slug))),
    );
    setRelatedFaqs(related);
    setDetailLoading(false);
  };

  const goHome = () => {
    setView('home');
    setActiveFaq(null);
  };

  const handleLinkPress = (url?: string) => {
    if (url) Linking.openURL(url);
  };

  const isGlossaryTab = activeTab?.type === 'glossary';

  return (
    <SafeAreaView style={s.root}>
      <StatusBar barStyle="dark-content" backgroundColor="#FFFFFF" />

      {/* Fixed siblings above the ScrollView — neither the shared app header
          nor the back button should scroll away with the content. */}
      <AppHeader navigation={navigation} onDrawerOpen={() => setDrawerOpen(true)} />

      {view !== 'home' && (
        <View style={s.topBar}>
          <BackButton onPress={goHome} />
        </View>
      )}

      {/* ── Hero (title + search) — fixed, does not scroll with content ── */}
      <View style={s.hero}>
        <Text style={s.heroTitle}>{heroTitle}</Text>
        <View style={s.searchOuter}>
          <View style={s.searchInputRow}>
            <SearchIcon />
            <TextInput
              style={s.searchInput}
              placeholder="Keyword search..."
              placeholderTextColor="#8F9098"
              value={query}
              onChangeText={setQuery}
              returnKeyType="search"
              onSubmitEditing={handleSearch}
            />
          </View>
          <TouchableOpacity style={s.searchBtn} onPress={handleSearch} activeOpacity={0.85}>
            <Text style={s.searchBtnText}>{'Search'}</Text>
          </TouchableOpacity>
        </View>
      </View>

      {loading ? (
        <View style={s.centerFill}>
          <ActivityIndicator size="large" color="#0C4D91" />
        </View>
      ) : errored ? (
        <View style={s.centerFill}>
          <Text style={s.errorText}>{"Couldn't load Help & Support. Pull down to try again."}</Text>
          <TouchableOpacity style={s.retryBtn} onPress={loadInitial} activeOpacity={0.85}>
            <Text style={s.viewAnswerText}>{'Retry'}</Text>
          </TouchableOpacity>
        </View>
      ) : (
        <ScrollView style={s.scroll} showsVerticalScrollIndicator={false} contentContainerStyle={s.scrollContent}>
          {/* ── Home: categories + FAQ/glossary list ────────────────────── */}
          {view === 'home' && (
            <View style={s.body}>
              <View style={s.categoryCard}>
                {tabs.map((tab, i) => {
                  const Icon = TAB_ICONS[tab.id] || GenericTabIcon;
                  return (
                    <React.Fragment key={tab.id}>
                      <TouchableOpacity style={s.categoryFrame} onPress={() => selectTab(tab)} activeOpacity={0.7}>
                        <Icon />
                        <Text style={[s.categoryLabel, activeTab?.id === tab.id && s.categoryLabelActive]}>
                          {tab.label}
                        </Text>
                      </TouchableOpacity>
                      {i < tabs.length - 1 && <CategoryDividerIcon />}
                    </React.Fragment>
                  );
                })}
              </View>

              {isGlossaryTab ? (
                <View style={s.faqList}>
                  <Text style={s.sectionHeading}>{activeTab?.heading || 'Glossary'}</Text>
                  <View style={s.glossarySearchBox}>
                    <SearchIcon />
                    <TextInput
                      style={s.glossarySearchInput}
                      placeholder="Search Glossary"
                      placeholderTextColor="#8F9098"
                      value={glossaryQuery}
                      onChangeText={setGlossaryQuery}
                      returnKeyType="search"
                      onSubmitEditing={handleGlossarySearch}
                    />
                  </View>
                  {glossary.map(g => (
                    <TouchableOpacity
                      key={g.id}
                      style={s.faqCard}
                      activeOpacity={0.7}
                      onPress={() => {
                        setGlossaryResult(g);
                        setView('search');
                      }}>
                      <Text style={s.faqQuestion}>{g.title}</Text>
                      <PlusIcon />
                    </TouchableOpacity>
                  ))}
                  {!glossary.length && <Text style={s.emptyText}>{'No glossary terms available.'}</Text>}
                </View>
              ) : (
                <View style={s.faqList}>
                  <Text style={s.sectionHeading}>{activeTab?.heading || 'Frequently Asked Questions'}</Text>
                  {faqs.map(f => (
                    <TouchableOpacity key={f.id} style={s.faqCard} activeOpacity={0.7} onPress={() => openFaq(f)}>
                      <Text style={s.faqQuestion}>{f.title}</Text>
                      <PlusIcon />
                    </TouchableOpacity>
                  ))}
                  {!faqs.length && <Text style={s.emptyText}>{'No FAQs in this category yet.'}</Text>}
                </View>
              )}
            </View>
          )}

          {/* ── Detail: answer + related FAQ ────────────────────────────── */}
          {view === 'detail' && (
            <View style={s.body}>
              {detailLoading || !activeFaq ? (
                <ActivityIndicator size="small" color="#0C4D91" />
              ) : (
                <>
                  <View style={s.answerCard}>
                    <Text style={s.answerHeading}>{activeFaq.title}</Text>
                    {activeFaqBlocks.map((block, i) =>
                      block.type === 'bullet' ? (
                        <View key={i} style={s.bulletRow}>
                          <BulletArrowIcon />
                          <Text style={s.answerText}>
                            {block.segments.map((seg, si) =>
                              seg.url ? (
                                <Text key={si} style={s.answerLink} onPress={() => handleLinkPress(seg.url)}>
                                  {seg.text}
                                </Text>
                              ) : (
                                <Text key={si}>{seg.text}</Text>
                              ),
                            )}
                          </Text>
                        </View>
                      ) : (
                        <Text key={i} style={s.answerText}>
                          {block.segments.map((seg, si) =>
                            seg.url ? (
                              <Text key={si} style={s.answerLink} onPress={() => handleLinkPress(seg.url)}>
                                {seg.text}
                              </Text>
                            ) : (
                              <Text key={si}>{seg.text}</Text>
                            ),
                          )}
                        </Text>
                      ),
                    )}
                  </View>

                  {!!relatedFaqs.length && (
                    <>
                      <Text style={s.relatedHeading}>{'Related FAQ'}</Text>
                      {relatedFaqs.map(rf => (
                        <View key={rf.id} style={s.relatedCard}>
                          <Text style={s.relatedQuestion}>{rf.title}</Text>
                          <TouchableOpacity style={s.viewAnswerBtn} onPress={() => openFaq(rf)} activeOpacity={0.85}>
                            <Text style={s.viewAnswerText}>{'View Answer'}</Text>
                          </TouchableOpacity>
                        </View>
                      ))}
                    </>
                  )}
                </>
              )}
            </View>
          )}

          {/* ── Search results ───────────────────────────────────────────── */}
          {view === 'search' && (
            <View style={s.body}>
              <Text style={s.sectionHeading}>{'Search Results:'}</Text>

              {isGlossaryTab ? (
                glossaryResult ? (
                  <View style={s.glossaryResultCard}>
                    <Text style={s.glossaryTerm}>{glossaryResult.title}</Text>
                    <Text style={s.glossaryDefinition}>{glossaryResult.content_text}</Text>
                  </View>
                ) : (
                  <Text style={s.emptyText}>{'No glossary term found.'}</Text>
                )
              ) : searchLoading ? (
                <ActivityIndicator size="small" color="#0C4D91" />
              ) : searchResults.length ? (
                searchResults.map(f => (
                  <View key={f.id} style={s.relatedCard}>
                    <Text style={s.relatedQuestion}>{f.title}</Text>
                    <TouchableOpacity style={s.viewAnswerBtn} onPress={() => openFaq(f)} activeOpacity={0.85}>
                      <Text style={s.viewAnswerText}>{'View Answer'}</Text>
                    </TouchableOpacity>
                  </View>
                ))
              ) : (
                <Text style={s.emptyText}>{'No results found.'}</Text>
              )}
            </View>
          )}
        </ScrollView>
      )}

      <ProfileDrawer visible={drawerOpen} onClose={() => setDrawerOpen(false)} navigation={navigation} />
    </SafeAreaView>
  );
};

// ─── Styles ─────────────────────────────────────────────────────────────────
const s = StyleSheet.create({
  root: {flex: 1, backgroundColor: '#FFFFFF'},
  scroll: {flex: 1},
  scrollContent: {flexGrow: 1, paddingBottom: 40},
  centerFill: {flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 32, gap: 16},
  errorText: {color: '#192546', fontFamily: 'Runda', fontSize: 14, textAlign: 'center'},
  retryBtn: {
    paddingVertical: 12,
    paddingHorizontal: 24,
    borderRadius: 5,
    backgroundColor: '#46B0E3',
  },
  emptyText: {color: '#8F9098', fontFamily: 'Runda', fontSize: 13, textAlign: 'center', paddingVertical: 12},

  topBar: {paddingHorizontal: 16, paddingTop: 8, paddingBottom: 4, backgroundColor: '#FFFFFF'},

  // ── Hero ──
  hero: {
    minHeight: 229,
    backgroundColor: '#0C4D91',
    paddingHorizontal: 16,
    paddingTop: 24,
    paddingBottom: 28,
    alignItems: 'center',
    justifyContent: 'center',
  },
  heroTitle: {
    color: '#FFFFFF',
    textAlign: 'center',
    fontFamily: 'Runda',
    fontSize: 24,
    fontWeight: '700',
    letterSpacing: 0.24,
    marginBottom: 20,
  },
  // Spec: outer frame is a true pill — height 50, radius 100 — with
  // overflow:'hidden' so the button's flat right edge gets clipped to that
  // pill shape instead of squaring off the corner.
  searchOuter: {
    width: '100%',
    maxWidth: 358,
    height: 50,
    flexDirection: 'row',
    alignItems: 'center',
    alignSelf: 'stretch',
    borderRadius: 100,
    overflow: 'hidden',
    shadowColor: '#000',
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.15,
    shadowRadius: 9.418,
    elevation: 3,
  },
  // Spec padding (10px 32px 10px 16px + button's 21/21/19/19) adds up to
  // MORE vertical space than the pill's fixed 50px height allows once both
  // children are stretched to fill it — that's what was clipping the text
  // top/bottom against the pill's overflow:'hidden'. Fix: children keep
  // horizontal padding only (spacing from the icon/edges) and size to their
  // own content height; the outer pill's alignItems:'center' (above)
  // vertically centers that content within the full 50px, so nothing gets
  // cut regardless of the literal vertical padding values.
  searchInputRow: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
    paddingLeft: 16,
    paddingRight: 32,
    backgroundColor: '#FFFFFF',
    // Fills the pill's full height so the white background doesn't leave a
    // gap above/below the input — content inside still centers via
    // alignItems above, so this doesn't reintroduce the clipping.
    alignSelf: 'stretch',
    justifyContent: 'center',
  },
  // Explicit height + lineHeight (well under the pill's available space) —
  // relying on textAlignVertical/includeFontPadding alone wasn't enough;
  // Android's EditText still measures its own intrinsic height taller than
  // the font, so centering the (oversized) intrinsic box against a fixed
  // parent height still clipped the glyphs. Pinning the input's own box to
  // a small known size removes that mismatch entirely.
  searchInput: {
    flex: 1,
    height: 20,
    lineHeight: 20,
    color: '#8F9098',
    fontFamily: 'Runda',
    fontSize: 16,
    padding: 0,
    margin: 0,
    includeFontPadding: false,
    textAlignVertical: 'center',
  },
  // Gradient (#4992DB → #084D92) approximated with a solid mid-tone —
  // swap to react-native-linear-gradient if/when the lib is added.
  searchBtn: {
    alignSelf: 'stretch',
    paddingHorizontal: 21,
    backgroundColor: '#1E6FB0',
    alignItems: 'center',
    justifyContent: 'center',
  },
  searchBtnText: {color: '#FFFFFF', fontFamily: 'Runda', fontSize: 14, fontWeight: '700'},

  body: {paddingHorizontal: 16, paddingTop: 24, gap: 24},

  // ── Category tabs ──
  // Spec: width 358, padding 8 8 6 8, radius 4.59, shadow — same card
  // treatment as the hero search bar.
  categoryCard: {
    alignSelf: 'stretch',
    maxWidth: 358,
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    borderRadius: 4.59,
    backgroundColor: '#FFFFFF',
    paddingTop: 8,
    paddingHorizontal: 8,
    paddingBottom: 6,
    shadowColor: '#000',
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.15,
    shadowRadius: 9.2,
    elevation: 3,
  },
  categoryFrame: {
    alignItems: 'center',
    gap: 3.5,
  },
  // Bumped from the 8px/500 spec value — read as too faint/small at real
  // device size, especially against the outline icons above it.
  categoryLabel: {
    color: '#192546',
    textAlign: 'center',
    fontFamily: 'Runda',
    fontSize: 10,
    fontWeight: '600',
    lineHeight: 13,
  },
  categoryLabelActive: {color: '#0C4D91', fontWeight: '700'},

  // ── FAQ list ──
  faqList: {gap: 12},
  sectionHeading: {
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 18,
    fontWeight: '700',
    letterSpacing: 0.09,
    marginBottom: 4,
  },
  faqCard: {
    flexDirection: 'row',
    padding: 16,
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: 10,
    borderRadius: 5,
    backgroundColor: '#FFFFFF',
    shadowColor: '#000',
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.15,
    shadowRadius: 9.4,
    elevation: 2,
  },
  faqQuestion: {
    flex: 1,
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 12,
    fontWeight: '700',
  },

  // ── Glossary search-within-category box ──
  // overflow:'hidden' — without it, TextInput's own intrinsic
  // height/internal padding (esp. on Android) can visually poke past the
  // 36px box even though the box's own layout height is correctly fixed.
  // paddingVertical would eat into the fixed 36px height and clip the
  // icon/text against overflow:'hidden' (same issue as the hero search
  // pill) — horizontal padding only, alignItems:'center' handles vertical
  // centering without shrinking the available content area.
  glossarySearchBox: {
    height: 36,
    flexDirection: 'row',
    alignItems: 'center',
    alignSelf: 'stretch',
    gap: 16,
    overflow: 'hidden',
    borderWidth: 1,
    borderColor: '#8F9098',
    borderRadius: 5,
    paddingHorizontal: 16,
    marginBottom: 4,
  },
  // Same fix as searchInput above — explicit height/lineHeight instead of
  // trusting Android's intrinsic EditText sizing to stay under the box.
  glossarySearchInput: {
    flex: 1,
    height: 18,
    lineHeight: 18,
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 14,
    padding: 0,
    margin: 0,
    includeFontPadding: false,
    textAlignVertical: 'center',
  },

  // ── Answer detail ──
  answerCard: {
    padding: 16,
    borderRadius: 5,
    backgroundColor: '#FFFFFF',
    gap: 10,
    shadowColor: '#000',
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.15,
    shadowRadius: 9.4,
    elevation: 2,
  },
  answerHeading: {
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 12,
    fontWeight: '700',
  },
  answerText: {
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 12,
    fontWeight: '400',
    lineHeight: 16,
    flex: 1,
  },
  answerLink: {color: '#0C4D91', textDecorationLine: 'underline'},
  bulletRow: {flexDirection: 'row', alignItems: 'flex-start', gap: 8},

  relatedHeading: {
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 18,
    fontWeight: '700',
    letterSpacing: 0.09,
    marginTop: 4,
    marginBottom: -8,
  },
  relatedCard: {
    padding: 16,
    borderRadius: 5,
    backgroundColor: '#FFFFFF',
    alignItems: 'center',
    gap: 10,
    shadowColor: '#000',
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.15,
    shadowRadius: 9.4,
    elevation: 2,
    marginTop: 12,
  },
  relatedQuestion: {
    alignSelf: 'stretch',
    color: '#192546',
    fontFamily: 'Runda',
    fontSize: 12,
    fontWeight: '700',
  },
  // minHeight instead of a fixed height — height + paddingVertical together
  // fight each other and clip the label (same fix as ResourceDetailScreen's
  // courseBtnPrimary/tocBtn).
  viewAnswerBtn: {
    minHeight: 36,
    paddingHorizontal: 16,
    paddingVertical: 10,
    justifyContent: 'center',
    alignItems: 'center',
    alignSelf: 'stretch',
    borderRadius: 5,
    backgroundColor: '#46B0E3',
  },
  viewAnswerText: {color: '#FFFFFF', fontFamily: 'Runda', fontSize: 13, fontWeight: '700'},

  // ── Glossary result ──
  glossaryResultCard: {
    padding: 16,
    borderRadius: 5,
    backgroundColor: '#FFFFFF',
    gap: 6,
    shadowColor: '#000',
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.15,
    shadowRadius: 9.4,
    elevation: 2,
  },
  glossaryTerm: {color: '#192546', fontFamily: 'Runda', fontSize: 13, fontWeight: '700'},
  glossaryDefinition: {color: '#192546', fontFamily: 'Runda', fontSize: 12, fontWeight: '400', lineHeight: 16},
});

export default HelpSupportScreen;
